UPDATE public.health_examination_sessions
SET status=#{status},updated_at=CURRENT_TIMESTAMP,row_version=row_version+1
WHERE id=#{id} AND organization_id=#{organizationId} AND row_version=#{expectedRowVersion} AND status=#{expectedStatus}

mapper.sql:
s.organization_id=#{organizationId}
AND (s.agreement_id=#{agreementId} OR s.agreement_id IS NULL)
AND s.session_date >= #{from}
AND s.session_date <= #{to}
AND s.activity=#{activity}
AND s.status=#{status}
AND LOWER(s.site_address) LIKE #{pattern} ESCAPE chr(92)

