s.session_date DESC, s.id ASC s.session_date ASC, s.id ASC s.activity DESC, s.id ASC s.activity ASC, s.id ASC s.status DESC, s.id ASC s.status ASC, s.id ASC s.created_at DESC, s.id ASC s.created_at ASC, s.id ASC s.id DESC s.id ASC
LIMIT #{limit} OFFSET #{offset}
